/* Account presentation only. All balances and qualifications come from server RPCs. */
window.MioDashboard=(()=>{
 const $=id=>document.getElementById(id);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=(n,d=3)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(Number(n)||0);
 const date=v=>v?new Date(v).toLocaleDateString('en-GB',{timeZone:'Asia/Karachi',day:'2-digit',month:'long',year:'numeric'}):'—';
 const icons={dashboard:'layout',profile:'user',network:'network',earnings:'chart',wallet:'wallet',transfer:'transfer',transactions:'history',ecommerce:'bag',orders:'box',packages:'diamond',security:'shield',seller:'store',sell:'store',workspace:'settings'};
 function icon(name){const shapes={layout:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',network:'<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="M12 8v5M5 16v-3h14v3"/>',chart:'<path d="M4 4v16h17M8 15l4-5 4 2 5-7"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18M16 13h5v4h-5z"/>',transfer:'<path d="M3 7h17l-4-4M21 17H4l4 4"/>',history:'<path d="M3 11a9 9 0 1 1 3 8M3 4v7h7M12 7v5l3 2"/>',bag:'<path d="M4 7h16l1 14H3zM8 7V5a4 4 0 0 1 8 0v2"/>',box:'<path d="M3 6l9-4 9 4v12l-9 4-9-4zM3 6l9 4 9-4M12 10v12"/>',diamond:'<path d="M3 7l4-4h10l4 4-9 14zM3 7h18M7 3l5 18 5-18"/>',shield:'<path d="M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6"/>',store:'<path d="M3 9l2-6h14l2 6M3 9v3h18V9M5 12v9h14v-9M9 21v-6h6v6"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.layout}</svg>`}
 let api,summary=null,financial=null,timer=null,request=0,currentPage='shop',serverOffset=0,rewardPreference={eligible:false,mode:'PPV',ppvUsed:0,ppvCap:110,locked:false},transactionPinConfigured=false,pinDialogRequest=null,authState={signedIn:false,admin:false,sellers:false,sellOpen:false};
 const pages=['dashboard','profile','wallet','transfer','transactions','network','network-graphical','earnings','ecommerce','orders','order','security','seller','sell','workspace','admin'];
 function newPage(id,title,subtitle=''){const p=document.createElement('section');p.className='page';p.id='page-'+id;p.innerHTML=`<div class="heading"><div><div class="eyebrow">My account</div><h1>${title}</h1><p>${subtitle}</p></div></div>`;return p}
 function setTransactionPinConfigured(value){transactionPinConfigured=!!value;const field=$('transferPin');if(field){field.value='';field.placeholder=transactionPinConfigured?'Enter your transaction PIN':'PIN setup will open first';field.closest('label')?.classList.toggle('pin-not-configured',!transactionPinConfigured)}const card=$('transactionPinForm')?.closest('.transaction-pin-card');card?.classList.toggle('pin-is-set',transactionPinConfigured);const status=$('transactionPinStatus');if(status&&transactionPinConfigured&&!status.textContent)status.textContent='Transaction PIN active hai. Aap isay yahan se change bhi kar sakte hain.'}
 function closePinDialog(value){const dialog=$('transactionPinDialog');if(dialog?.open)dialog.close();const resolve=pinDialogRequest;pinDialogRequest=null;if(resolve)resolve(value)}
 function openPinDialog(mode,reason){const dialog=$('transactionPinDialog'),form=$('transactionPinDialogForm');if(!dialog||!form)return Promise.resolve(null);if(pinDialogRequest)closePinDialog(null);form.reset();form.dataset.mode=mode;$('transactionPinDialogStatus').textContent='';$('transactionPinDialogTitle').textContent=mode==='setup'?'Set your transaction PIN':'Enter transaction PIN';$('transactionPinDialogMessage').textContent=mode==='setup'?`Aap ne abhi transaction PIN set nahi ki. ${reason} se pehle 4–6 digit PIN create karein.`:`${reason} confirm karne ke liye apna transaction PIN enter karein.`;$('transactionPinDialogConfirmWrap').hidden=mode!=='setup';$('transactionPinDialogConfirm').required=mode==='setup';$('transactionPinDialogValue').autocomplete=mode==='setup'?'new-password':'current-password';$('transactionPinDialogSubmit').textContent=mode==='setup'?'Set transaction PIN':'Confirm transaction';dialog.showModal();setTimeout(()=>$('transactionPinDialogValue')?.focus(),0);return new Promise(resolve=>{pinDialogRequest=resolve})}
 async function requestTransactionPin(reason='Continue this transaction'){if(!transactionPinConfigured){const setup=await openPinDialog('setup',reason);if(setup!=='__configured__')return null}return openPinDialog('verify',reason)}
 function mount(options){api=options;const main=$('main-content');
  const shell=document.createElement('div');shell.id='memberAccountShell';shell.className='member-account-shell hidden';shell.innerHTML=`<aside class="member-sidebar" id="memberSidebar"><div class="sidebar-brand"><img src="/market-is-online-logo.png" alt="Market is Online"></div><nav id="memberAccountNav" aria-label="My dashboard"></nav><button class="sidebar-signout" type="button" id="dashboardSignOut">Sign out</button></aside><div class="member-workspace"><header class="member-topbar"><button type="button" id="dashboardMenu" aria-label="Toggle account menu" aria-controls="memberSidebar" aria-expanded="false">${icon('menu')}</button><strong id="accountPageTitle">Dashboard</strong><span class="member-header-date">${date(new Date())}</span><button type="button" id="dashboardNotifications" aria-label="Notifications" aria-expanded="false">${icon('bell')}</button></header><section class="dashboard-notifications" id="dashboardNotificationList" hidden><h3>Notifications</h3><p>No new notifications.</p></section><div class="member-page-content" id="memberPageContent"></div></div>`;main.append(shell);
  const body=$('memberPageContent');for(const id of ['dashboard','profile','transfer','transactions'])body.append(newPage(id,({dashboard:'Dashboard',profile:'My profile',transfer:'Transfer MIO',transactions:'Transaction history'})[id]));
  for(const id of pages){if(id==='workspace'||id==='admin')continue;const p=$('page-'+id);if(p&&p.parentElement!==body)body.append(p)}
  const transfer=$('transferForm')?.closest('section.card'),history=$('mioHistory')?.closest('section.card');if(transfer)$('page-transfer').append(transfer);if(history)$('page-transactions').append(history);const price=document.createElement('div');price.className='mio-price-banner';price.innerHTML='<span>MIO reference price</span><strong>1 MIO = <span id="mioReferencePrice">PKR 300</span></strong><small>Admin-set reference price; transfers remain in MIO Points.</small>';$('page-transactions').prepend(price);
  $('page-wallet').querySelectorAll(':scope>.layout').forEach(layout=>{if(!layout.children.length)layout.remove()});
  const pointCard=$('ppvHistory').closest('section.card'),otherCard=$('otherPoints').closest('section.card');
  pointCard.querySelector('h2').textContent='Points activity';pointCard.querySelector('.card-head p').textContent='PPV, DP, GP and binary point records in one compact list.';
  pointCard.querySelector('.card-body').append($('otherPoints'));$('otherPoints').hidden=true;otherCard.remove();
  const receive=document.createElement('section');receive.className='card dashboard-receive-card';receive.innerHTML='<div class="card-head"><h2>Receive MIO Points</h2></div><div class="card-body"><small>Your member code</small><strong id="dashboardReceiveCode" class="code">—</strong><button class="btn small copy-code" id="dashboardCopyCode" data-copy="">Copy member code</button><p>Share this code with the sender. Existing package transfer rules apply.</p></div>';$('page-transfer').prepend(receive);
  const profile=document.createElement('div');profile.id='dashboardProfile';$('page-profile').append(profile);
  const securityBody=$('page-security')?.querySelector('.card-body');if(securityBody&&!$('transactionPinForm')){securityBody.insertAdjacentHTML('beforeend','<hr class="dashboard-divider"><div class="transaction-pin-card"><h2>Transaction PIN</h2><p class="helper">MIO transfer aur package activation ke liye 4 se 6 digits ka PIN lazmi hai.</p><form id="transactionPinForm" class="stack-form"><label>New transaction PIN<input id="transactionPin" name="pin" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" required autocomplete="new-password" placeholder="4–6 digits"></label><label>Confirm PIN<input id="transactionPinConfirm" name="confirm" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" required autocomplete="new-password" placeholder="Repeat PIN"></label><button class="btn primary" type="submit">Save transaction PIN</button><small id="transactionPinStatus" class="helper" role="status"></small></form></div>');}
  if(!$('transactionPinDialog')){document.body.insertAdjacentHTML('beforeend','<dialog id="transactionPinDialog" class="transaction-pin-dialog"><form id="transactionPinDialogForm" class="transaction-pin-dialog-card"><div class="transaction-pin-dialog-icon">'+icon('shield')+'</div><div><span class="transaction-pin-kicker">Secure transaction</span><h2 id="transactionPinDialogTitle">Set your transaction PIN</h2><p id="transactionPinDialogMessage">Create a private 4–6 digit PIN before continuing.</p></div><label>Transaction PIN<input id="transactionPinDialogValue" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="new-password" required placeholder="4–6 digits"></label><label id="transactionPinDialogConfirmWrap">Confirm PIN<input id="transactionPinDialogConfirm" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="new-password" placeholder="Repeat PIN"></label><p id="transactionPinDialogStatus" class="helper" role="alert"></p><div class="transaction-pin-actions"><button class="btn" type="button" id="transactionPinDialogCancel">Cancel</button><button class="btn primary" type="submit" id="transactionPinDialogSubmit">Set transaction PIN</button></div></form></dialog>');}
  const transferForm=$('transferForm');if(transferForm&&!$('transferPin')){const wrap=document.createElement('label');wrap.className='transfer-pin-field';wrap.innerHTML='Transaction PIN<input id="transferPin" type="password" inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9]{4,6}" autocomplete="current-password" placeholder="Enter PIN when requested">';const submit=transferForm.querySelector('button[type="submit"],button');if(submit)transferForm.insertBefore(wrap,submit);else transferForm.append(wrap);}
  $('transactionPinForm')?.addEventListener('submit',async e=>{e.preventDefault();const pin=$('transactionPin')?.value||'',confirm=$('transactionPinConfirm')?.value||'',status=$('transactionPinStatus');if(pin!==confirm){if(status)status.textContent='PINs match nahin kar rahe.';return}const result=await api.rpc('set_transaction_pin',{p_pin:pin});if(status)status.textContent=result.error?(result.error.message||'PIN save nahin ho saka.'):'Transaction PIN save ho gaya.';if(!result.error){setTransactionPinConfigured(true);e.target.reset()}});
  $('transactionPinDialogForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,mode=form.dataset.mode||'verify',pin=$('transactionPinDialogValue').value,status=$('transactionPinDialogStatus');status.textContent='';if(mode==='setup'){const confirm=$('transactionPinDialogConfirm').value;if(pin!==confirm){status.textContent='Dono PIN match nahin kar rahe.';return}const button=$('transactionPinDialogSubmit');button.disabled=true;const result=await api.rpc('set_transaction_pin',{p_pin:pin});button.disabled=false;if(result.error){status.textContent=result.error.message||'PIN save nahin ho saka.';return}setTransactionPinConfigured(true);closePinDialog('__configured__');return}closePinDialog(pin)});
  $('transactionPinDialogCancel')?.addEventListener('click',()=>closePinDialog(null));
  const nav=document.querySelector('.top .nav');let dashboard=nav.querySelector('[data-page="dashboard"]');if(!dashboard){dashboard=document.createElement('button');dashboard.dataset.page='dashboard';dashboard.textContent='My Dashboard';nav.append(dashboard)}
  $('page-dashboard').innerHTML='<div class="dashboard-loading">Loading your account overview…</div>';
  $('dashboardMenu').onclick=()=>{const open=shell.classList.toggle('sidebar-open');$('dashboardMenu').setAttribute('aria-expanded',String(open))};
  $('dashboardSignOut').onclick=()=>$('signOutBtn')?.click();
  $('dashboardNotifications').onclick=()=>{const list=$('dashboardNotificationList');list.hidden=!list.hidden;$('dashboardNotifications').setAttribute('aria-expanded',String(!list.hidden))};
  document.addEventListener('click',e=>{const b=e.target.closest('[data-dashboard-detail]');if(b)showDetail(b.dataset.dashboardDetail);const generation=e.target.closest('[data-dashboard-generation]');if(generation)showDetail('generation',Number(generation.dataset.dashboardGeneration));const tree=e.target.closest('[data-dashboard-tree]');if(tree){$('networkKind').value=tree.dataset.dashboardTree;api.go('network-graphical');api.renderNetwork().catch(api.error)}});
 }
 function renderAccountNav(){const target=$('memberAccountNav');if(!target)return;target.setAttribute('aria-label','My dashboard');const links=[['dashboard','My Dashboard'],['profile','My profile'],['network','My network'],['earnings','Earnings'],['wallet','My wallet'],['transfer','Transfer MIO'],['transactions','Transaction history'],['ecommerce','E-commerce'],['orders','My orders'],['packages','Membership plans'],['security','Security'],...(authState.sellers?[['seller','Seller centre']]:[]),...(authState.sellOpen?[['sell','Sell with us']]:[]),...(authState.admin?[['workspace','Admin Dashboard']]:[])];target.innerHTML=links.map(([id,label])=>`<button type="button" data-page="${id}" ${id==='workspace'?'id="dashboardAdminNav"':''} class="${currentPage===id?'active':''}">${icon(icons[id])}<span>${label}</span></button>`).join('')}
 function updateAuth(signedIn,admin,sellers,sellOpen){if(!$('memberAccountNav'))return;authState={signedIn,admin,sellers,sellOpen};renderAccountNav();document.querySelectorAll('.top .nav [data-page]').forEach(b=>{const page=b.dataset.page,publicPage=['shop','packages'].includes(page),memberPage=signedIn&&page==='dashboard',adminPage=signedIn&&admin&&page==='workspace';b.classList.toggle('hidden',!(publicPage||memberPage||adminPage))});document.querySelectorAll('.footer a[href="#orders"]').forEach(a=>a.classList.toggle('hidden',!signedIn));if(!signedIn){setTransactionPinConfigured(false);closePinDialog(null);summary=null;financial=null;request++;clearInterval(timer);$('page-dashboard').innerHTML='';$('dashboardProfile').replaceChildren();$('dashboardReceiveCode').textContent='—';$('dashboardCopyCode').dataset.copy='';$('memberAccountShell').classList.add('hidden');$('memberAccountShell').classList.remove('admin-workspace-active');document.body.classList.remove('member-dashboard-active');} }
 function navigate(page,signedIn){currentPage=page;for(const id of ['orders','order']){const target=$('page-'+id);if(target)(signedIn?$('memberPageContent'):$('main-content')).append(target)}const active=signedIn&&pages.includes(page)&&page!=='workspace'&&page!=='admin';$('memberAccountShell')?.classList.toggle('hidden',!active);document.body.classList.toggle('member-dashboard-active',active);$('memberAccountShell')?.classList.remove('sidebar-open');$('dashboardMenu')?.setAttribute('aria-expanded','false');$('accountPageTitle').textContent=page==='network-graphical'?'Graphical':({dashboard:'Dashboard',profile:'My profile',transactions:'Transaction history',transfer:'Transfer MIO'})[page]||page.replaceAll('-',' ').replace(/^./,s=>s.toUpperCase());renderAccountNav();if(active&&page==='dashboard')refresh().catch(api.error)}
 function setFinancial(value){
  financial=value;
  const cap=Number(rewardPreference.ppvCap)||110;
  const totalPpv=Math.max(0,Number(value?.ppv)||0);
  if(totalPpv>=cap){
    rewardPreference={...rewardPreference,eligible:true,mode:'MIO',ppvUsed:totalPpv,ppvCap:cap,locked:true};
  }
  if(summary)render();
}
 async function refresh(){if(!api.signedIn())return;const turn=++request;const result=await api.rpc('my_member_dashboard');if(result.error)throw result.error;if(turn!==request||!api.signedIn())return;if(!result.data||Array.isArray(result.data))return;summary=result.data;serverOffset=new Date(summary.server_now).getTime()-Date.now();if(!Number.isFinite(serverOffset))serverOffset=0;render()}
 function metric(label,value,sub,art,detail){const tag=detail?'button':'div';return `<${tag} class="dashboard-metric" ${detail?`type="button" data-dashboard-detail="${detail}"`:''}><span class="dashboard-metric-icon">${icon(art)}</span><div><span>${label}</span><strong>${number(value)}</strong><small>${sub}${detail?' ↗':''}</small></div></${tag}>`}
 function locked(title,art,subtitle='Coming soon'){return `<div class="dashboard-future" aria-label="${title}, locked, coming soon"><span class="dashboard-future-icon">${icon(art)}</span><div><h3>${title}</h3><span>${icon('lock')} ${subtitle}</span></div></div>`}
 function render(){if(!summary||!financial)return;const s=summary,g=s.generation||{},b=s.binary||{},active=s.package_active,f=financial,plan=s.package_name||'Free account',promo=s.activation_offer||{},levels=Array.from({length:10},(_,i)=>{const n=i+1,state=n<=g.active_generations?'open':n<=g.allowed_generations?'pending':'locked';return `<button type="button" class="dashboard-level ${state}" data-dashboard-generation="${n}" aria-label="Generation ${n}: ${state==='open'?'unlocked':state==='pending'?'qualification pending':'not in package'}"><span>${n}</span>${state==='locked'?icon('lock'):state==='open'?'<small>✓</small>':'<small>—</small>'}</button>`}).join('');
  $('page-dashboard').innerHTML=`<section class="dashboard-reward-switch" id="dashboardRewardSwitch">${rewardSwitchHtml()}</section><div class="dashboard-offer-row"><section class="dashboard-offer"><span class="offer-visual">${icon('clock')}</span><div><h2>Package Activation Bonus</h2><p>${active?(promo.enabled!==false?`Sponsor bonus + ${number((promo.welcome_rate||0)*100,2)}% Welcome Bonus for your first 15 days`:'Normal package sponsor rate applies'):(promo.feature_enabled===false?'Welcome Bonus is currently unavailable':'Activate a plan to start your 15-day offer')}</p><strong id="dashboardOfferTimer" role="timer"></strong><small id="dashboardOfferNote"></small></div></section>${locked('Annual maintenance','lock')}${locked('Monthly maintenance','lock')}</div>
  <section class="dashboard-identity"><div class="dashboard-person">${api.safeImage(s.profile_photo_url)?`<img src="${esc(api.safeImage(s.profile_photo_url))}" alt="${esc(s.full_name)}">`:`<span class="dashboard-avatar">${icon('user')}</span>`}<div><h1>${esc(s.full_name)}</h1><span class="dashboard-member-code"><span class="code">${esc(s.member_code)}</span><button type="button" class="copy-code" data-copy="${esc(s.member_code)}" aria-label="Copy member code" title="Copy member code">⧉ <span>Copy</span></button></span><small>Enrolled · ${date(s.enrolled_at)}</small><button class="text-button" type="button" data-page="profile">My profile ↗</button></div></div><div class="dashboard-package"><img src="${api.tierImage(s.package_code)}" alt=""><div><small>Current membership</small><strong>${esc(plan)}</strong><span class="dashboard-status ${active?'active':''}">${active?'Active':'Plan not active'}</span></div></div><button type="button" class="dashboard-total-earned" data-page="earnings"><span>Total Network Earnings</span><strong>${number(f.earned,4)} <small>MIO</small></strong><small>View details →</small></button></section>
  <div class="dashboard-balance-row"><button type="button" class="dashboard-balance" data-page="wallet">${icon('wallet')}<div><span>MIO Points</span><strong>${number(f.balance,4)} <small>MIO</small></strong><small>My cash points →</small></div></button><button type="button" class="dashboard-balance" data-page="packages">${icon('bag')}<div><span>Personal Shopping Points</span><strong>${number(f.ppv,4)} <small>PPV</small></strong><small>Grow my plan →</small></div></button><div class="dashboard-personal-points"><span>Personal Generation Points</span><div><span>GP <b>${number(s.personal_gp)}</b></span></div></div></div>
  <div class="dashboard-stat-row">${metric('Direct sponsors',g.direct_count,`${number(g.active_direct_count)} active`,'user','directs')}${metric('Direct Points · DP',g.direct_points,'Working qualification points','diamond')}${metric('TNGP',g.tngp,'Total Network Generation Points','network')}</div>
  <div class="dashboard-network-row"><section class="dashboard-panel"><div class="dashboard-panel-title"><h2>Total Network</h2><button type="button" data-dashboard-detail="generations">${number(g.total_generation_network)} members ↗</button></div><p class="dashboard-muted">Generation network · Click to explore each generation</p><h3 class="dashboard-subtitle">Binary team</h3><div class="dashboard-binary-sides"><button type="button" data-dashboard-detail="left"><span>Left team</span><strong>${number(b.left_team_count)}</strong><small>Members ↗</small></button><button type="button" data-dashboard-detail="right"><span>Right team</span><strong>${number(b.right_team_count)}</strong><small>Members ↗</small></button></div></section><section class="dashboard-panel"><div class="dashboard-panel-title"><h2>Active Generations</h2><strong>${number(g.active_generations)} / ${number(g.allowed_generations)}</strong></div><div class="dashboard-levels">${levels}</div><p class="dashboard-muted">Green: unlocked · Grey: pending · Lock: higher plan required</p><div class="dashboard-graphical"><span>Explore your team visually</span><button type="button" class="btn primary small" data-page="network-graphical">Graphical →</button></div></section></div>
  <section class="dashboard-panel dashboard-tnbp"><div class="dashboard-panel-title"><h2>TNBP <small>Total Network Binary Points</small></h2><button type="button" class="text-button" data-dashboard-tree="binary">Binary tree ↗</button></div><div class="dashboard-binary-sides"><div><span>Left TNBP</span><strong>${number(b.total_left_bp)}</strong><small>Carry forward: ${number(b.left_bp)} BP</small></div><div><span>Right TNBP</span><strong>${number(b.total_right_bp)}</strong><small>Carry forward: ${number(b.right_bp)} BP</small></div></div><div class="dashboard-binary-pending"><span>Current pending shares <b>${Number(s.pending_shares||0).toFixed(3)}</b></span><span>${number(s.share_points_each_side)} BP each side = 1 share</span><span>Network earnings on hold <b>${number(f.held,4)} MIO</b></span></div></section>
  <section class="dashboard-detail-panel dashboard-panel" id="dashboardMemberDrilldown" hidden aria-live="polite"></section>
  <section class="dashboard-panel dashboard-wallet-future"><div class="dashboard-panel-title"><h2>Wallets & Income Distribution</h2><span class="dashboard-muted">Future features</span></div><div class="dashboard-future-wallets">${locked('Proceed Wallet · 100%','wallet')}${locked('Cash Wallet','wallet')}${locked('Shopping Points','bag')}${locked('Promotion Points','diamond')}</div></section>`;
  $('dashboardProfile').innerHTML=`<section class="card"><div class="card-body dashboard-profile-details"><h2>${esc(s.full_name)}</h2><p class="code">${esc(s.member_code)}</p><p>Enrolled · ${date(s.enrolled_at)}</p><p>${esc(plan)} · ${active?'Active':'Plan not active'}</p><p>Manage your profile picture and referral links in My Network.</p><button type="button" class="btn" data-page="network">Profile picture & team links</button></div></section>`;
  $('dashboardReceiveCode').textContent=s.member_code||'—';$('dashboardCopyCode').dataset.copy=s.member_code||'';clearInterval(timer);tick();timer=setInterval(tick,1000);
 }
 function rewardSwitchHtml(){const mode=rewardPreference.mode==='MIO'?'MIO':'PPV',eligible=rewardPreference.eligible,used=Number(rewardPreference.ppvUsed)||0,cap=Number(rewardPreference.ppvCap)||110,locked=!!rewardPreference.locked||used>=cap;return `<div><span>Shopping reward preference</span><small>${locked?`Shopping PPV cap complete (${number(used,4)} / ${number(cap,4)}). Ab future rewards sirf MIO mein milenge.`:eligible?'Future shopping reward ka mode select karein.':'MIO rewards ke liye membership plan activate karein.'}</small></div><div class="dashboard-reward-toggle" role="group" aria-label="Shopping reward preference"><button type="button" data-reward-mode="PPV" aria-pressed="${mode==='PPV'}" class="${mode==='PPV'?'active':''} ${locked?'is-locked':''}" ${locked?'disabled aria-label="PPV locked at '+number(cap,4)+'"':''}>${locked?icon('lock'):''}<span>PPV${locked?' locked':''}</span></button><button type="button" data-reward-mode="MIO" aria-pressed="${mode==='MIO'}" class="${mode==='MIO'?'active':''}" ${eligible?'':'disabled'}><span>MIO${eligible?'':' locked'}</span></button></div>`}
 function setRewardPreference(value={}){rewardPreference={eligible:!!value.eligible,mode:value.mode==='MIO'?'MIO':'PPV',ppvUsed:Number(value.ppvUsed)||0,ppvCap:Number(value.ppvCap)||110,locked:!!value.locked};const target=$('dashboardRewardSwitch');if(target){const locked=rewardPreference.locked||rewardPreference.ppvUsed>=rewardPreference.ppvCap;target.innerHTML=rewardSwitchHtml();target.dataset.ppvLocked=String(locked);target.classList.toggle('ppv-limit-locked',locked)}}
 function tick(){const target=$('dashboardOfferTimer'),note=$('dashboardOfferNote');if(!target||!summary)return;const offer=summary.activation_offer||{},remaining=offer.ends_at?new Date(offer.ends_at).getTime()-(Date.now()+serverOffset):0,eligible=summary.package_active&&offer.eligible&&remaining>0;target.textContent=eligible?`${Math.floor(remaining/86400000)}d ${String(Math.floor(remaining/3600000)%24).padStart(2,'0')}h ${String(Math.floor(remaining/60000)%60).padStart(2,'0')}m ${String(Math.floor(remaining/1000)%60).padStart(2,'0')}s`:summary.package_active?(offer.enabled!==false?'Offer ended':'Not included'):(offer.feature_enabled===false?'Currently off':'Not started');note.textContent=eligible?`Ends ${date(offer.ends_at)} · New direct package activations`:summary.package_active?`Normal sponsor rate: ${number(offer.normal_rate*100,2)}%`:offer.feature_enabled===false?'Normal package sponsor rate will apply after activation':'Available once after your first plan activation';}
 function memberRows(rows){return rows.length?`<div class="dashboard-member-list">${rows.map(m=>`<div class="dashboard-member-row">${m.profile_photo_url&&api.safeImage(m.profile_photo_url)?`<img src="${esc(api.safeImage(m.profile_photo_url))}" alt="">`:`<span class="dashboard-member-avatar">${icon('user')}</span>`}<div><strong>${esc(m.full_name)}</strong><small>${esc(m.member_code)} · ${esc(api.planName(m.package))}</small><small>Joined ${date(m.joined_at)}</small></div><span class="dashboard-status ${m.status==='active'?'active':''}">${esc(m.status)}</span></div>`).join('')}</div>`:'<p class="dashboard-muted">No members in this generation.</p>'}
 function showDetail(kind,level){const host=$('dashboardMemberDrilldown');if(!host||!summary)return;const g=summary.generation||{},generations=g.generations||[];host.hidden=false;
  if(kind==='directs')host.innerHTML=`<div class="dashboard-panel-title"><h2>Direct sponsors · ${number(g.direct_count)}</h2><span>${number(g.direct_points)} DP</span></div>${memberRows(g.directs||[])}`;
  else if(kind==='generation'){const row=generations.find(g=>Number(g.level)===level);host.innerHTML=`<div class="dashboard-panel-title"><h2>Generation ${level} · ${number(row?.member_count)} members</h2><span class="dashboard-muted">${row?.unlocked?'Earning active':row?.allowed?'Qualification pending':'Not in current plan'}</span></div>${memberRows(row?.members||[])}`;}
  else if(kind==='generations')host.innerHTML='<div class="dashboard-panel-title"><h2>Generation network</h2></div>'+generations.map(g=>`<button type="button" class="dashboard-generation-row" data-dashboard-generation="${g.level}"><span>Generation ${g.level}</span><strong>${number(g.member_count)} members →</strong></button>`).join('');
  else{const side=kind.toUpperCase();host.innerHTML=`<div class="dashboard-panel-title"><h2>${kind==='left'?'Left':'Right'} binary team</h2></div><p class="dashboard-muted">Open Graphical to explore placement and individual member information.</p><button type="button" class="btn primary small" data-dashboard-tree="binary">Open ${side} team in Binary Tree</button>`;}
  host.scrollIntoView({behavior:'smooth',block:'nearest'});
 }
 return {mount,updateAuth,navigate,refresh,setFinancial,setRewardPreference,setTransactionPinConfigured,hasTransactionPin:()=>transactionPinConfigured,requestTransactionPin,icon,showDetail};
})();
